extends CharacterBody3D

@export var move_speed : float = 5.0
@export var acceleration : float = 10.0
@export var air_control : float = 5.0
@export var jump_velocity : float = 4.5
@export var gravity : float = 9.8

func _physics_process(delta):
	# Handle gravity
	if not is_on_floor():
		velocity.y -= gravity * delta

	# Handle jump
	if Input.is_action_just_pressed("jump") and is_on_floor():
		velocity.y = jump_velocity

	# Get input direction
	var input_dir := Input.get_vector("left", "right", "forward", "back")
	var direction := (transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()

	# Apply acceleration based on whether on ground or in air
	var target_speed = move_speed * input_dir.length()
	var current_acceleration = acceleration if is_on_floor() else air_control

	if direction:
		# Accelerate towards input direction
		var horizontal_velocity = Vector3(velocity.x, 0, velocity.z)
		var new_horizontal = horizontal_velocity.move_toward(direction * target_speed, current_acceleration * delta)
		velocity.x = new_horizontal.x
		velocity.z = new_horizontal.z
	else:
		# Decelerate to zero
		var horizontal_velocity = Vector3(velocity.x, 0, velocity.z)
		var new_horizontal = horizontal_velocity.move_toward(Vector3.ZERO, current_acceleration * delta)
		velocity.x = new_horizontal.x
		velocity.z = new_horizontal.z

	move_and_slide()
